/* ══ HERO AVATAR: 3D bust + scroll-driven education journey ══
   Drop-in: add <script src="hero-avatar.js" defer></script> before </body>.
   It wraps #hero in a tall scroll track, pins the hero, and moves the camera
   from the front view to each education sticker as you scroll.
   Edit the JOURNEY list below to change the text on the cards. */
(function () {
  'use strict';

  /* ── content: one card per stop, in scroll order ── */
  /* side: which cheek the sticker is on, as seen on screen ('left' or 'right');
     the card appears on the opposite side. */
  var JOURNEY = [
    {
      sticker: 0, side: 'left', kind: 'education', /* owl sticker */
      date: 'apr 2025 → present',
      title: 'universität des saarlandes',
      degree: 'm.sc. media informatics',
      place: 'saarbrücken, germany',
      note: 'hci, interactive systems, 3d visualisation with blender, generative arts and design.'
    },
    {
      sticker: 1, side: 'left', kind: 'education', /* crest sticker */
      date: 'oct 2019 → dec 2023',
      title: 'government college university lahore',
      degree: 'bachelor of computer science (hons.)',
      place: 'lahore, pakistan',
      note: 'relevant coursework: software engineering, advanced software engineering, software quality assurance, object oriented programming, database systems, introduction to machine learning, communication &amp; presentation skills; final year project graded a.'
    },
    {
      sticker: 3, side: 'right', kind: 'experience', /* S sticker */
      date: 'jun 2024 → may 2025',
      title: 'sumato solutions',
      degree: 'ux/ui designer',
      place: '',
      note: 'pos module adopted across 10+ client deployments; redesigned 5 core erp modules for non-technical users.'
    },
    {
      sticker: 2, side: 'right', kind: 'experience', /* im sticker */
      date: 'oct 2023 → jan 2024',
      title: 'mashkraft',
      degree: 'ui/ux design intern',
      place: '',
      note: 'designed the considracare websites for pakistan and canada, and worked on its mobile and web apps for caregivers and families.'
    }
  ];

  var STICKERS = ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];

  var hero = document.getElementById('hero');
  if (!hero) return;
  var inner = hero.querySelector('.hero-inner');

  /* ── styles ── */
  var css = [
    /* overflow-x:hidden on body stops position:sticky working and clips the full-width hero,
       so the page is clipped at the window edge instead */
    'html{overflow-x:clip}body{overflow-x:visible}',
    '#heroJourney{position:relative;height:' + (140 + JOURNEY.length * 120) + 'vh}',
    '#heroJourney>#hero{position:sticky;top:0;height:100vh;height:100svh;width:100vw;max-width:none;margin-left:calc(50% - 50vw);margin-right:0}',
    '#hero .ha-canvas{position:absolute;inset:0;width:100%;height:100%;z-index:1;pointer-events:none;display:block}',
    '#hero .hero-inner{z-index:2}',
    '#hero .ha-slot{height:clamp(200px,40vh,520px);margin:0 auto 4px;width:min(500px,90vw)}',
    '#hero .ha-fade{transition:none;will-change:opacity,transform}',
    '#hero.ha-wide .hero-inner{position:static;width:min(1280px,calc(100vw - 64px));margin-inline:auto;padding-left:52%;box-sizing:border-box}',
    '#hero.ha-wide .ha-slot{position:absolute;left:max(32px,calc(50vw - 640px));margin:0;width:calc(min(1280px,100vw - 64px) * 0.5)!important}',
    '#hero.ha-wide .hero-name-row{display:inline-block}',
    '.ha-cards{position:absolute;inset:0;z-index:3;pointer-events:none}',
    '.ha-card{position:absolute;right:clamp(16px,6vw,96px);top:50%;width:min(380px,36vw);',
    '  transform:translateY(-50%);background:var(--bg-card,#FBF9F3);color:var(--ink,#181510);',
    '  border:1px solid var(--border,#181510);border-radius:var(--radius,14px);padding:22px 24px;',
    '  opacity:0;visibility:hidden;box-shadow:0 18px 40px -24px rgba(0,0,0,.35)}',
    '.ha-card.is-right{right:auto;left:clamp(16px,6vw,96px)}',
    '.ha-eyebrow{display:flex;justify-content:space-between;gap:12px;font-family:var(--sans,"Space Mono",monospace);',
    '  font-size:11px;letter-spacing:.06em;text-transform:lowercase;color:var(--ink-3,#8F8A7C);margin:0 0 14px}',
    '.ha-eyebrow b{color:var(--accent,#F83B0A);font-weight:700}',
    '.ha-title{font-family:var(--serif,"Bricolage Grotesque",sans-serif);font-weight:700;font-size:clamp(22px,2.4vw,30px);',
    '  line-height:1.05;letter-spacing:-.02em;text-transform:lowercase;margin:0 0 10px;text-wrap:balance}',
    '.ha-degree{font-family:var(--sans,"Space Mono",monospace);font-size:13px;margin:0 0 4px;color:var(--ink,#181510)}',
    '.ha-place{font-family:var(--sans,"Space Mono",monospace);font-size:12px;margin:0 0 14px;color:var(--ink-3,#8F8A7C)}',
    '.ha-note{font-family:var(--sans,"Space Mono",monospace);font-size:12px;line-height:1.6;margin:0;color:var(--ink-2,#3A352C)}',
    '@media (max-width:767px){',
    '  .ha-card,.ha-card.is-right{left:16px;right:16px;width:auto;top:auto;bottom:calc(100px + env(safe-area-inset-bottom,0px));transform:none;padding:18px}',
    '}'
  ].join('\n');
  var style = document.createElement('style');
  style.textContent = css;
  document.head.appendChild(style);

  /* ── DOM: scroll track, avatar slot, canvas, cards ── */
  var track = document.createElement('div');
  track.id = 'heroJourney';
  hero.parentNode.insertBefore(track, hero);
  track.appendChild(hero);

  var slot = document.createElement('div');
  slot.className = 'ha-slot';
  slot.setAttribute('aria-hidden', 'true');
  if (inner) inner.insertBefore(slot, inner.firstChild);

  /* the avatar takes all the height the hero text leaves free */
  /* the hero is pulled up under the nav bar so the whole first screen is usable;
     NAV_SPACE is the height the nav bar covers */
  var NAV_SPACE = 0;
  function sizeSlot() {
    if (!inner) return;
    track.style.marginTop = '0px';
    NAV_SPACE = Math.round(track.getBoundingClientRect().top + window.scrollY);
    track.style.marginTop = (-NAV_SPACE) + 'px';
    var wide = window.innerWidth >= 1024;
    hero.classList.toggle('ha-wide', wide);
    if (wide) {
      /* wide screens: avatar fills the left column at nearly full height, text on the right */
      inner.style.marginTop = NAV_SPACE + 'px';
      inner.style.paddingBottom = '';
      var hw = hero.clientHeight - NAV_SPACE - 32;
      slot.style.height = hw + 'px';
      slot.style.top = (NAV_SPACE + 8) + 'px';
      slot.style.width = '';
      return;
    }
    inner.style.marginTop = '';
    inner.style.paddingBottom = '';
    slot.style.top = '';
    slot.style.height = '0px';
    slot.style.marginTop = (NAV_SPACE + 8) + 'px';
    inner.style.paddingBottom = '0px';
    var rest = inner.offsetHeight;   /* text block plus the top margin */
    /* on phones the nav links float in a dock at the bottom; keep the hero text above it */
    var dock = 0, g = document.querySelector('.sb-nav-group');
    if (g && getComputedStyle(g).position === 'fixed') dock = window.innerHeight - g.getBoundingClientRect().top + 12;
    inner.style.paddingBottom = dock + 'px';
    var h = Math.max(180, hero.clientHeight - rest - 24 - dock);
    slot.style.height = h + 'px';
    slot.style.width = Math.min(h * 0.95, window.innerWidth - 32) + 'px';
  }
  sizeSlot();
  addEventListener('resize', sizeSlot);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(sizeSlot);
  addEventListener('load', sizeSlot);

  var fadeEls = [];
  if (inner) Array.prototype.forEach.call(inner.children, function (el) { if (el !== slot) { el.classList.add('ha-fade'); fadeEls.push(el); } });
  var images = hero.querySelector('.images');
  if (images) { images.classList.add('ha-fade'); fadeEls.push(images); }

  var cardsWrap = document.createElement('div');
  cardsWrap.className = 'ha-cards';
  function kindIndex(i) {
    var k = JOURNEY[i].kind, all = JOURNEY.filter(function (x) { return x.kind === k; });
    return (all.indexOf(JOURNEY[i]) + 1) + '/' + all.length;
  }
  var cards = JOURNEY.map(function (j, i) {
    var c = document.createElement('article');
    c.className = 'ha-card' + (j.side === 'right' ? ' is-right' : '');
    c.innerHTML =
      '<p class="ha-eyebrow"><span>' + j.kind + ' <b>' + kindIndex(i) + '</b></span><span>' + (j.date || '') + '</span></p>' +
      '<h2 class="ha-title">' + j.title + '</h2>' +
      (j.degree ? '<p class="ha-degree">' + j.degree + '</p>' : '') +
      (j.place ? '<p class="ha-place">' + j.place + '</p>' : '') +
      (j.note ? '<p class="ha-note">' + j.note + '</p>' : '');
    cardsWrap.appendChild(c);
    return c;
  });
  hero.appendChild(cardsWrap);

  /* ── load three.js, then build ── */
  function load(src, cb) {
    if (window.THREE) return cb();
    var s = document.createElement('script');
    s.src = src; s.onload = cb;
    s.onerror = function () { slot.style.display = 'none'; };
    document.head.appendChild(s);
  }
  load('https://cdn.jsdelivr.net/npm/three@0.149.0/build/three.min.js', build);

  function build() {
    var T = THREE;
    if (T.ColorManagement) T.ColorManagement.legacyMode = false;
    var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

    var renderer = new T.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.outputEncoding = T.sRGBEncoding;
    renderer.toneMapping = T.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.92;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = T.PCFSoftShadowMap;
    renderer.domElement.className = 'ha-canvas';
    hero.insertBefore(renderer.domElement, hero.firstChild);

    const scene=new T.Scene();
    const camera=new T.PerspectiveCamera(28,1,0.1,60);
    
    // lights
    scene.add(new T.HemisphereLight(0xfff4e6,0x5b5048,0.6));
    const key=new T.DirectionalLight(0xfff1df,1.5);
    key.position.set(3,5,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);
    key.shadow.camera.left=-3;key.shadow.camera.right=3;key.shadow.camera.top=4;key.shadow.camera.bottom=-2;key.shadow.bias=-0.0008;key.shadow.radius=4;
    scene.add(key);
    const fill=new T.DirectionalLight(0xdfe8ff,0.45);fill.position.set(-4,2,3);scene.add(fill);
    const rim=new T.DirectionalLight(0xffffff,0.8);rim.position.set(-2,4,-5);scene.add(rim);
    /* on the dark theme, extra rim light outlines the black hair against the background */
    const rim2=new T.DirectionalLight(0xfff0dc,0);rim2.position.set(3,3,-4);scene.add(rim2);
    function themeLights(){const dark=document.documentElement.classList.contains('dark');rim.intensity=dark?2.6:0.8;rim2.intensity=dark?1.8:0;}
    themeLights();new MutationObserver(themeLights).observe(document.documentElement,{attributes:true,attributeFilter:['class']});
    
    // textures
    function canvasTex(w,h,draw){const c=document.createElement('canvas');c.width=w;c.height=h;draw(c.getContext('2d'),w,h);const t=new T.CanvasTexture(c);t.encoding=T.sRGBEncoding;return t;}
    function rnd(a,b){return a+Math.random()*(b-a)}
    // face: sphere UV, front (+z) is u=0.25; canvas y = theta/PI * h
    const faceTex=canvasTex(1024,512,(g,w,h)=>{
      g.fillStyle='#c28763';g.fillRect(0,0,w,h);
      const cx=256;
      // cheeks warmth
      [[-70],[70]].forEach(([dx])=>{const r=g.createRadialGradient(cx+dx,262,2,cx+dx,262,40);r.addColorStop(0,'rgba(214,110,90,.22)');r.addColorStop(1,'rgba(214,110,90,0)');g.fillStyle=r;g.fillRect(cx+dx-45,215,90,90);});
      // clean shaven: just a whisper of jaw shading
      const jaw=g.createLinearGradient(0,330,0,512);jaw.addColorStop(0,'rgba(120,70,45,0)');jaw.addColorStop(1,'rgba(120,70,45,.10)');g.fillStyle=jaw;g.fillRect(cx-210,330,420,182);
    });
    const knitTex=canvasTex(256,256,(g,w,h)=>{
      g.fillStyle='#f3ead0';g.fillRect(0,0,w,h);
      for(let x=0;x<w;x+=16){
        for(let y=0;y<h;y+=12){
          g.fillStyle='#dccfa9';g.beginPath();g.ellipse(x+5,y+6,3,6,-0.4,0,Math.PI*2);g.ellipse(x+11,y+6,3,6,0.4,0,Math.PI*2);g.fill();
        }
      }
    });
    knitTex.wrapS=knitTex.wrapT=T.RepeatWrapping;knitTex.repeat.set(10,5);
    
    const shirtTex=canvasTex(256,256,(g,w,h)=>{
      g.fillStyle='#5f5b3e';g.fillRect(0,0,w,h);
      for(let i=0;i<9000;i++){g.fillStyle=Math.random()<.5?'rgba(255,250,220,.05)':'rgba(0,0,0,.07)';g.fillRect(rnd(0,w),rnd(0,h),rnd(1,5),1);}
    });
    shirtTex.wrapS=shirtTex.wrapT=T.RepeatWrapping;shirtTex.repeat.set(6,3);
    const denimTex=canvasTex(512,512,(g,w,h)=>{
      g.fillStyle='#34557f';g.fillRect(0,0,w,h);
      for(let y=-w;y<h;y+=4){g.strokeStyle=(y/4)%2?'rgba(255,255,255,.07)':'rgba(10,20,40,.10)';g.lineWidth=2;g.beginPath();g.moveTo(0,y);g.lineTo(w,y+w);g.stroke();}
      for(let i=0;i<14000;i++){g.fillStyle=Math.random()<.5?'rgba(230,240,255,.06)':'rgba(5,15,35,.08)';g.fillRect(rnd(0,w),rnd(0,h),rnd(1,6),1);}
      const fade=g.createRadialGradient(w*.5,h*.45,10,w*.5,h*.45,w*.6);fade.addColorStop(0,'rgba(200,220,245,.10)');fade.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=fade;g.fillRect(0,0,w,h);
    });
    denimTex.wrapS=denimTex.wrapT=T.RepeatWrapping;denimTex.repeat.set(3,2);
    const teeTex=canvasTex(128,128,(g,w,h)=>{g.fillStyle='#f4f3ef';g.fillRect(0,0,w,h);for(let i=0;i<2500;i++){g.fillStyle='rgba(0,0,0,.025)';g.fillRect(rnd(0,w),rnd(0,h),2,1);}});
    teeTex.wrapS=teeTex.wrapT=T.RepeatWrapping;teeTex.repeat.set(4,4);
    const M={
      denim:new T.MeshStandardMaterial({color:0xffffff,map:denimTex,roughness:.92}),
      denimDark:new T.MeshStandardMaterial({color:0xb8c4d6,map:denimTex,roughness:.92}),
      tee:new T.MeshStandardMaterial({color:0xffffff,map:teeTex,roughness:.85}),
      stitch:new T.MeshStandardMaterial({color:0xd9913f,roughness:.6}),
      copper:new T.MeshStandardMaterial({color:0xb87333,metalness:.75,roughness:.3}),
      skin:new T.MeshStandardMaterial({color:0xffffff,map:faceTex,roughness:.55}),
      skinLid:null,
      skinPlain:new T.MeshStandardMaterial({color:0xc28763,roughness:.55}),
      skinDark:new T.MeshStandardMaterial({color:0xa86e4b,roughness:.6}),
      hair:new T.MeshStandardMaterial({color:0x0e0a09,roughness:.55,metalness:.05}),
      white:new T.MeshStandardMaterial({color:0xf8f4ec,roughness:.15}),
      iris:new T.MeshStandardMaterial({color:0x4e301f,roughness:.2}),
      pupil:new T.MeshStandardMaterial({color:0x0d0907,roughness:.1}),
      lip:new T.MeshStandardMaterial({color:0x8a4636,roughness:.5}),
      knit:new T.MeshStandardMaterial({color:0xffffff,map:knitTex,roughness:.95}),
      shirt:new T.MeshStandardMaterial({color:0xffffff,map:shirtTex,roughness:.9}),
      button:new T.MeshStandardMaterial({color:0x3b3826,roughness:.5}),
      zip:new T.MeshStandardMaterial({color:0xb8b2a2,metalness:.6,roughness:.35}),
    };
    function mesh(geo,mat,pos,scale,rot){const m=new T.Mesh(geo,mat);if(pos)m.position.set(...pos);if(scale)m.scale.set(...scale);if(rot)m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;return m;}
    
    const root=new T.Group();scene.add(root);
    
    // torso: open denim jacket over a white crew-neck tee
    const body=new T.Group();root.add(body);
    const ZS=0.52;
    const prof=[[0.0,0.9],[0.3,0.9],[0.31,0.66],[0.5,0.6],[0.85,0.5],[1.06,0.38],[1.15,0.2],[1.17,-0.05],[1.12,-0.5],[1.08,-1.0],[0.0,-1.0]];
    const torsoGeo=new T.LatheGeometry(prof.slice().reverse().map(([r,y])=>new T.Vector2(r,y)),96);
    body.add(mesh(torsoGeo,M.denim,[0,0,0],[1,1,ZS]));
    const radiusAt=y=>{for(let i=2;i<prof.length-2;i++){const[a,ya]=prof[i],[b,yb]=prof[i+1];if(y<=ya&&y>=yb)return a+(b-a)*(ya-y)/(ya-yb);}return 0.3;};
    const frontZ=y=>radiusAt(y)*ZS;
    const surfAt=(x,y,lift)=>{const r=radiusAt(y);return Math.sqrt(Math.max(0,r*r-x*x))*ZS+lift;};
    body.add(mesh(new T.CylinderGeometry(0.29,0.31,0.6,32),M.skinDark,[0,0.92,0]));
    // the tee showing in the jacket opening: widens toward the waist
    const openW=y=>0.2+Math.max(0,0.6-y)*0.13;
    {
      const nx=12,ny=40,geo=new T.PlaneGeometry(1,1,nx,ny),p=geo.attributes.position;
      for(let i=0;i<p.count;i++){const u=p.getX(i),v=p.getY(i)+0.5;const y=-1.0+v*1.62;const x=u*2*openW(y);p.setXYZ(i,x,y,surfAt(x,y,0.006));}
      geo.computeVertexNormals();body.add(mesh(geo,M.tee));
    }
    // crew neckline
    body.add(mesh(new T.TorusGeometry(0.3,0.045,12,48),M.tee,[0,0.66,0.02],[1,1,0.95],[Math.PI/2+0.25,0,0]));
    // jacket front edges with orange top-stitching
    [-1,1].forEach(s=>{
      const e=[],st=[];
      for(let y=0.62;y>=-1.0;y-=0.04){const x=s*openW(y);e.push(new T.Vector3(x,y,surfAt(x,y,0.02)));const xs=s*(openW(y)+0.07);st.push(new T.Vector3(xs,y,surfAt(xs,y,0.012)));}
      body.add(mesh(new T.TubeGeometry(new T.CatmullRomCurve3(e),60,0.035,8),M.denim));
      body.add(mesh(new T.TubeGeometry(new T.CatmullRomCurve3(st),60,0.007,5),M.stitch));
      // yoke seam across the chest
      const yk=[];for(let a=0;a<=1.0001;a+=0.05){const x=s*(openW(0.32)+0.04+a*0.75);const y=0.3-a*0.06;yk.push(new T.Vector3(x,y,surfAt(x,y,0.012)));}
      body.add(mesh(new T.TubeGeometry(new T.CatmullRomCurve3(yk),24,0.008,5),M.stitch));
      // chest flap pocket with a copper button
      const px=s*0.58,py=0.05,pz=surfAt(px,py,0.012),ang=s*Math.asin(Math.min(0.95,Math.abs(px)/radiusAt(py)))*0.9;
      const pk=new T.Group();pk.position.set(px,py,pz);pk.rotation.y=ang;body.add(pk);
      pk.add(mesh(new T.BoxGeometry(0.3,0.1,0.03),M.denimDark,[0,0.08,0.01]));
      pk.add(mesh(new T.BoxGeometry(0.3,0.012,0.032),M.stitch,[0,0.035,0.012]));
      pk.add(mesh(new T.CylinderGeometry(0.03,0.03,0.025,16),M.copper,[0,0.06,0.035],null,[Math.PI/2,0,0]));
      // big denim collar folded over the shoulders
      { const cx0=s*0.34, cy0=0.52, c=new T.Group(); c.position.set(cx0,cy0,surfAt(cx0,cy0,0.03)); c.rotation.set(-0.35,s*0.5,s*0.45); body.add(c);
        c.add(mesh(new T.ConeGeometry(0.2,0.46,3),M.denim,[0,0,0],[1,1,0.18],[0,0,Math.PI]));
        const cs=[];for(let a=0;a<=1.0001;a+=0.25)cs.push(new T.Vector3(-0.15+a*0.3*0.5,-0.05-a*0.12,0.03));
      }
    });
    // collar band behind the neck
    body.add(mesh(new T.TorusGeometry(0.36,0.07,12,48,Math.PI*1.25),M.denim,[0,0.72,-0.04],[1,1,0.9],[Math.PI/2+0.15,0,Math.PI*-0.125+Math.PI]));
    // copper shank buttons down one edge
    [0.2,-0.2,-0.6].forEach(y=>{const x=openW(y)+0.08;body.add(mesh(new T.CylinderGeometry(0.035,0.035,0.025,16),M.copper,[x,y,surfAt(x,y,0.03)],null,[Math.PI/2,0,0]));});

    // arms in denim sleeves, resting at his sides
    function makeHand(){
      const h=new T.Group();
      h.add(mesh(new T.SphereGeometry(0.15,24,16),M.skinPlain,[0,-0.13,0],[1,1.12,0.5]));
      [-0.075,-0.025,0.025,0.075].forEach((x,i)=>{const l=[0.13,0.16,0.155,0.12][i];h.add(mesh(new T.CapsuleGeometry(0.034,l,6,10),M.skinPlain,[x*1.05,-0.27-l/2,0.0],null,[0,0,x*0.6]));});
      h.add(mesh(new T.CapsuleGeometry(0.038,0.11,6,10),M.skinPlain,[0.15,-0.12,0.02],null,[0,0,0.9]));
      return h;
    }
    function makeArm(s){
      const sh=new T.Group();sh.position.set(s*0.98,0.32,0);body.add(sh);
      sh.add(mesh(new T.CapsuleGeometry(0.19,0.5,8,16),M.denim,[0,-0.33,0]));
      const el=new T.Group();el.position.set(0,-0.66,0);sh.add(el);
      el.add(mesh(new T.CapsuleGeometry(0.165,0.42,8,16),M.denim,[0,-0.28,0]));
      el.add(mesh(new T.CylinderGeometry(0.17,0.17,0.1,24),M.denimDark,[0,-0.58,0]));
      el.add(mesh(new T.TorusGeometry(0.17,0.008,6,32),M.stitch,[0,-0.55,0],null,[Math.PI/2,0,0]));
      const wr=new T.Group();wr.position.set(0,-0.62,0);el.add(wr);
      wr.add(mesh(new T.CylinderGeometry(0.075,0.085,0.1,16),M.skinPlain,[0,-0.03,0]));
      const hand=makeHand();hand.scale.set(-s*1.25,1.25,1.25);wr.add(hand);
      return {sh,el,wr,s};
    }
    const arms=[makeArm(-1),makeArm(1)];

    // head (pivot at neck)
    const head=new T.Group();head.position.set(0,1.0,0);root.add(head);
    const H=(x,y,z)=>[x,y-1.0,z];
    const HX=0.9,HY=1.0,HZ=0.93,HC=1.62;
    const jawF=ny=>1-0.2*Math.max(0,-ny)**1.3;
    const skullGeo=new T.SphereGeometry(1,96,64);
    {const p=skullGeo.attributes.position;for(let i=0;i<p.count;i++){const y=p.getY(i),f=jawF(y);p.setX(i,p.getX(i)*f);p.setZ(i,p.getZ(i)*(y<0?1-0.06*(-y):1));}skullGeo.computeVertexNormals();}
    const skull=mesh(skullGeo,M.skin,H(0,HC,0),[HX,HY,HZ]);head.add(skull);
    function surfZ(x,y){const ny=(y-HC)/HY,nx=x/(HX*jawF(ny));return HZ*(ny<0?1-0.06*(-ny):1)*Math.sqrt(Math.max(0,1-nx*nx-ny*ny));}
    // ears
    [-1,1].forEach(s=>{head.add(mesh(new T.SphereGeometry(0.22,24,16),M.skinPlain,H(s*0.88,1.6,-0.02),[0.42,1,0.75],[0,s*0.3,0]));head.add(mesh(new T.SphereGeometry(0.1,16,12),M.skinDark,H(s*0.92,1.6,0.02),[0.3,1,0.6]));});
    
    // eyes
    const eyes=[];
    [-1,1].forEach(s=>{
      const x=s*0.31,y=1.72,z=surfZ(x,y)-0.09;
      const g=new T.Group();g.position.set(...H(x,y,z));head.add(g);
      const look=new T.Group();g.add(look);
      look.add(mesh(new T.SphereGeometry(0.165,32,24),M.white));
      const cap=(r,th,mat)=>{const m=mesh(new T.SphereGeometry(r,32,12,0,Math.PI*2,0,th),mat);m.rotation.x=Math.PI/2;return m;};
      look.add(cap(0.1665,0.62,M.iris));
      look.add(cap(0.167,0.3,M.pupil));
      const hl=mesh(new T.SphereGeometry(0.022,12,8),new T.MeshBasicMaterial({color:0xffffff}),[0.045,0.05,0.158]);look.add(hl);
      // upper lid: hemisphere that rotates down to close
      const lid=new T.Group();g.add(lid);
      lid.add(mesh(new T.SphereGeometry(0.178,32,16,0,Math.PI*2,0,Math.PI/2),M.skinPlain));
      lid.rotation.x=-0.5;
      // lash line
      const lash=mesh(new T.TorusGeometry(0.172,0.012,6,24,Math.PI*0.75),M.hair,[0,0,0],null,[0,0,Math.PI*0.125]);lid.add(lash);lash.rotation.x=Math.PI/2;lash.rotation.z=Math.PI*0.125;
      // lower lid
      const low=mesh(new T.SphereGeometry(0.172,32,8,0,Math.PI*2,Math.PI*0.62,Math.PI*0.38),M.skinPlain);low.rotation.x=0.35;g.add(low);
      eyes.push({g,look,lid,side:s});
    });
    
    // brows
    [-1,1].forEach(s=>{
      const x=s*0.32,y=1.97+(s>0?0.03:0);
      const b=mesh(new T.CapsuleGeometry(0.042,0.26,6,12),M.hair,H(x,y,surfZ(x,y)+0.01),null,[0,s*0.35,Math.PI/2-s*0.06]);
      head.add(b);
    });
    // nose
    head.add(mesh(new T.CapsuleGeometry(0.075,0.26,8,16),M.skin,H(0,1.57,surfZ(0,1.57)+0.02),null,[-0.28,0,0]));
    head.add(mesh(new T.SphereGeometry(0.105,24,16),M.skinPlain,H(0,1.43,surfZ(0,1.43)+0.08),[1.05,0.9,0.9]));
    [-1,1].forEach(s=>head.add(mesh(new T.SphereGeometry(0.06,16,12),M.skinPlain,H(s*0.085,1.41,surfZ(0,1.41)+0.04),[1,0.8,0.9])));
    // mouth: closed smile + dimples
    const smile=mesh(new T.TorusGeometry(0.2,0.024,8,32,Math.PI*0.5),M.lip,H(0,1.30,surfZ(0,1.14)+0.05),[1,0.75,1],[0,0,Math.PI*1.225]);
    head.add(smile);
    
    // stickers on the cheeks: first two on the viewer's left, last two on the right
    const loader=new T.TextureLoader();const stickerCenters=[];const stickerNormals=[];const STICKER_Y=[];
    function sticker(url,cx,cy,size,rot){
      const tex=loader.load(url);tex.encoding=T.sRGBEncoding;tex.anisotropy=4;
      const n=14,geo=new T.PlaneGeometry(1,1,n,n),p=geo.attributes.position,c=Math.cos(rot),s=Math.sin(rot);
      for(let i=0;i<p.count;i++){
        const u=p.getX(i)*size,v=p.getY(i)*size;
        const x=cx+u*c-v*s,y=cy+u*s+v*c;
        p.setXYZ(i,x,y-1.0,surfZ(x,y)+0.006);
      }
      geo.computeVertexNormals();
      const m=new T.Mesh(geo,new T.MeshStandardMaterial({map:tex,transparent:true,alphaTest:0.05,roughness:0.35,polygonOffset:true,polygonOffsetFactor:-2}));
      m.receiveShadow=true;head.add(m);
      stickerCenters.push(new T.Vector3(cx,cy-1.0,surfZ(cx,cy)+0.01));
  stickerNormals.push(new T.Vector3(cx/(HX*HX),(cy-HC)/(HY*HY),surfZ(cx,cy)/(HZ*HZ)).normalize());
    }
    {
      const S=STICKERS;
      sticker(S[0],-0.46,1.49,0.32,0.12);STICKER_Y[0]=1.49;STICKER_Y[1]=1.2;STICKER_Y[2]=1.49;STICKER_Y[3]=1.2;
      sticker(S[1],-0.44,1.2,0.33,-0.1);
      sticker(S[2],0.46,1.49,0.29,-0.12);
      sticker(S[3],0.44,1.2,0.3,0.1);
    }
    
    // hair: swept across the forehead toward the viewer's left, short sides
    const hair=new T.Group();head.add(hair);
    hair.add(mesh(new T.SphereGeometry(1,48,32),M.hair,H(0,2.04,-0.12),[0.97,0.74,0.98]));
    hair.add(mesh(new T.SphereGeometry(1,48,32),M.hair,H(0,1.66,-0.33),[0.93,0.95,0.72]));
    [-1,1].forEach(s=>hair.add(mesh(new T.SphereGeometry(0.35,32,24),M.hair,H(s*0.84,1.86,-0.04),[0.42,0.72,0.95])));
    const lobe=(r,p,sc,rot)=>hair.add(mesh(new T.SphereGeometry(r,40,28),M.hair,H(...p),sc,rot));
    lobe(0.55,[0.32,2.34,0.38],[1.1,0.55,0.9],[0.2,0,-0.3]);
    lobe(0.55,[-0.16,2.3,0.58],[1.2,0.48,0.7],[0.45,0,0.3]);
    lobe(0.34,[-0.64,2.14,0.46],[1.0,0.7,0.7],[0.3,0,0.8]);
    lobe(0.5,[0.0,2.52,0.12],[1.2,0.45,1.0],[0.1,0,-0.12]);
    lobe(0.45,[-0.48,2.42,0.18],[1.0,0.5,0.95],[0.1,0,0.35]);
    lobe(0.42,[0.6,2.28,0.08],[0.95,0.55,1.0],[0,0,-0.55]);
    lobe(0.4,[0.3,2.5,-0.25],[1.1,0.5,1.0],[0,0,-0.2]);

    /* ── camera keyframes (p = scroll progress through the track) ──
       tgt: what the camera looks at (a point, or a sticker index)
       off: camera offset from the target; yaw/pitch: head turn
       frame: where the subject sits ('slot' = above the name, 'full', 'left') */
    var START = 0.12, END = 0.9, L = (END - START) / JOURNEY.length;
    var K = [
      { p: 0.00, tgt: [0, 1.2, 0], off: [0, 0.2, 7.2], yaw: 0, pitch: 0, frame: 'slot', follow: 1 },
      { p: START - 0.02, tgt: [0, 1.25, 0], off: [0, 0.15, 7.4], yaw: 0, pitch: 0, frame: 'full', follow: 0.6 }
    ];
    var CARD_RANGES = [];
    JOURNEY.forEach(function (j, i) {
      var s = j.side === 'right' ? -1 : 1;           /* mirror for the other cheek */
      var low = STICKER_Y[j.sticker] < 1.35;
      var yaw = (low ? 0.4 : 0.5) * s, pitch = low ? -0.12 : 0.02, up = low ? 0.06 : 0.32;
      var a = START + L * i;
      var swing = i > 0 && JOURNEY[i - 1].side !== j.side;
      /* swing through a front view when moving to the other cheek */
      if (swing) K.push({ p: a + L * 0.05, tgt: [0, 1.3, 0], off: [0, 0.2, 7.0], yaw: 0, pitch: 0, frame: 'full', follow: 0.3 });
      /* arrive on the cheek, then push in until the logo fills the shot while the card is up */
      K.push({ p: a + L * 0.28, tgt: i, up: up, dist: 4.4, yaw: yaw, pitch: pitch, frame: j.side, follow: 0.1 });
      K.push({ p: a + L * 0.5, tgt: i, up: up, dist: 2.0, yaw: yaw, pitch: pitch, frame: j.side, follow: 0.05 });
      K.push({ p: a + L * 0.85, tgt: i, up: up, dist: 1.85, yaw: yaw * 1.03, pitch: pitch, frame: j.side, follow: 0.05 });
      CARD_RANGES.push([a + L * (swing ? 0.3 : 0.25), a + L * 1.02]);
    });
    K.push({ p: 0.96, tgt: [0, 1.0, 0], off: [1.5, 0.45, 8.4], yaw: -0.15, pitch: 0, frame: 'full', follow: 0.6 });
    K.push({ p: 1.00, tgt: [0, 1.0, 0], off: [1.5, 0.45, 8.4], yaw: -0.15, pitch: 0, frame: 'full', follow: 0.6 });

    var v3 = function (a) { return new T.Vector3(a[0], a[1], a[2]); };
    var tmp = new T.Vector3();
    var tmpN = new T.Vector3();
    /* camera offset: either a fixed vector, or straight out from the sticker's surface */
    function offsetOf(k) {
      if (k.dist == null) return v3(k.off);
      tmpN.copy(stickerNormals[JOURNEY[k.tgt].sticker]).transformDirection(head.matrixWorld);
      return tmpN.clone().multiplyScalar(k.dist).add(new T.Vector3(0, (k.up || 0.06) * k.dist, 0));
    }
    function targetOf(k) {
      if (typeof k.tgt === 'number') { tmp.copy(stickerCenters[JOURNEY[k.tgt].sticker]); head.localToWorld(tmp); return tmp.clone(); }
      return v3(k.tgt);
    }
    function ease(t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; }
    function smooth(a, b, x) { var t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); }
    function lerp(a, b, t) { return a + (b - a) * t; }

    /* frame rects in canvas pixels */
    function rectFor(name, W, Hh) {
      var mobile = W < 768;
      if (name === 'slot') {
        var hr = hero.getBoundingClientRect(), sr = slot.getBoundingClientRect();
        return { x: sr.left - hr.left, y: sr.top - hr.top, w: sr.width, h: sr.height };
      }
      if (name === 'left') return mobile ? { x: 0, y: 0, w: W, h: Hh * 0.55 } : { x: 0, y: 0, w: W * 0.6, h: Hh };
      if (name === 'right') return mobile ? { x: 0, y: 0, w: W, h: Hh * 0.55 } : { x: W * 0.4, y: 0, w: W * 0.6, h: Hh };
      return { x: 0, y: 0, w: W, h: Hh };
    }
    function lerpRect(a, b, t) { return { x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t), w: lerp(a.w, b.w, t), h: lerp(a.h, b.h, t) }; }

    var W = 1, Hh = 1;
    function size() {
      W = hero.clientWidth; Hh = hero.clientHeight; renderer.setSize(W, Hh, false);
    }
    size();
    new ResizeObserver(size).observe(hero);

    /* place the camera's picture inside rect r of the canvas */
    var shift = new T.Matrix4();
    function applyFrame(r) {
      camera.aspect = r.w / r.h;
      camera.updateProjectionMatrix();
      var sx = r.w / W, sy = r.h / Hh;
      var tx = ((r.x + r.w / 2) / W) * 2 - 1, ty = -(((r.y + r.h / 2) / Hh) * 2 - 1);
      shift.set(sx, 0, 0, tx, 0, sy, 0, ty, 0, 0, 1, 0, 0, 0, 0, 1);
      camera.projectionMatrix.premultiply(shift);
      camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();
    }

    /* scroll progress */
    function progress() {
      var r = track.getBoundingClientRect();
      var total = track.offsetHeight - innerHeight;
      return total > 0 ? Math.min(1, Math.max(0, -r.top / total)) : 0;
    }

    var tx = 0, ty = 0, lastMove = -1e9;
    addEventListener('pointermove', function (e) { tx = (e.clientX / innerWidth) * 2 - 1; ty = (e.clientY / innerHeight) * 2 - 1; lastMove = performance.now(); }, { passive: true });

    var visible = true;
    new IntersectionObserver(function (es) { visible = es[0].isIntersecting; }, { rootMargin: '100px' }).observe(track);

    var clock = new T.Clock(), time = 0, ps = progress(), yaw = 0, pitch = 0, nextBlink = 1.5, blinkT = -1;
    var camPos = new T.Vector3(), camTgt = new T.Vector3();

    function frame() {
      requestAnimationFrame(frame);
      var dt = Math.min(clock.getDelta(), 0.05);
      if (!visible) return;
      time += dt;
      var p = progress();
      ps += (p - ps) * (1 - Math.pow(0.0005, dt));
      if (Math.abs(p - ps) < 1e-4) ps = p;

      /* find keyframe segment */
      var i = 0; while (i < K.length - 2 && ps > K[i + 1].p) i++;
      var a = K[i], b = K[i + 1], t = ease(Math.min(1, Math.max(0, (ps - a.p) / (b.p - a.p))));

      /* cursor follow, faded out during the journey */
      var gx = tx, gy = ty;
      if (performance.now() - lastMove > 2500) { gx = Math.sin(time * 0.45) * 0.45; gy = Math.sin(time * 0.31) * 0.15 - 0.05; }
      var follow = lerp(a.follow, b.follow, t);
      var k = 1 - Math.pow(0.002, dt);
      yaw += (lerp(a.yaw, b.yaw, t) + gx * 0.55 * follow - yaw) * k;
      pitch += (lerp(a.pitch, b.pitch, t) + gy * 0.32 * follow - pitch) * k;
      var breathe = reduce ? 0 : Math.sin(time * 1.6);
      head.rotation.y = yaw;
      head.rotation.x = pitch + (reduce ? 0 : Math.sin(time * 0.8) * 0.015);
      head.rotation.z = -yaw * 0.08 + (reduce ? 0 : Math.sin(time * 0.6) * 0.02);
      root.position.y = breathe * 0.012;
      body.scale.set(1 + breathe * 0.006, 1 + breathe * 0.008, 1);
      root.rotation.y = yaw * 0.18;
      /* arms rest at his sides */
      arms.forEach(function (A) { A.sh.rotation.z = A.s * 0.1; A.el.rotation.z = A.s * -0.05; A.wr.rotation.z = 0; });
      root.updateMatrixWorld(true);
      eyes.forEach(function (e) { e.look.rotation.y = gx * 0.35 * Math.max(follow, 0.3); e.look.rotation.x = gy * 0.22 * Math.max(follow, 0.3); });
      nextBlink -= dt; if (nextBlink <= 0) { blinkT = 0; nextBlink = 2.5 + Math.random() * 3; }
      var bl = 0; if (blinkT >= 0) { blinkT += dt; bl = blinkT < 0.22 ? Math.sin(blinkT / 0.22 * Math.PI) : 0; if (blinkT > 0.22) blinkT = -1; }
      eyes.forEach(function (e) { e.lid.rotation.x = -0.5 + bl * 1.95; });

      /* camera */
      camTgt.copy(targetOf(a)).lerp(targetOf(b), t);
      camPos.copy(offsetOf(a)).lerp(offsetOf(b), t).add(camTgt);
      camera.position.copy(camPos);
      camera.lookAt(camTgt);
      var fr = lerpRect(rectFor(a.frame, W, Hh), rectFor(b.frame, W, Hh), t);
      applyFrame(fr);
      /* while the bust sits above the name, cut it off at the slot's bottom edge */
      var cut = a.frame === 'slot' ? lerp(fr.y + fr.h, Hh, t) : Hh;
      renderer.setScissorTest(cut < Hh - 0.5);
      renderer.setScissor(0, Hh - cut, W, cut);

      /* hero text fades out as the journey begins */
      var f = 1 - smooth(0.0, 0.09, ps);
      for (var n = 0; n < fadeEls.length; n++) {
        fadeEls[n].style.opacity = f;
        fadeEls[n].style.transform = 'translateY(' + ((1 - f) * -24) + 'px)';
        fadeEls[n].style.visibility = f < 0.01 ? 'hidden' : '';
      }

      /* cards */
      cards.forEach(function (c, ci) {
        var r = CARD_RANGES[ci];
        var o = Math.min(smooth(r[0], r[0] + 0.06, ps), 1 - smooth(r[1] - 0.06, r[1], ps));
        c.style.opacity = o;
        c.style.visibility = o < 0.01 ? 'hidden' : 'visible';
        var mobile = W < 768;
        c.style.transform = (mobile ? '' : 'translateY(-50%) ') + 'translateY(' + ((1 - o) * 24) + 'px)';
      });

      renderer.render(scene, camera);
    }
    frame();
  }
})();
